insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('PFUTP 4(2)(e): market nexus', 'An accounting irregularity becomes relevant to price manipulation where dissemination creates a false appearance of financial health/valuation, induces investors, or distorts price discovery.', 'REL paras 198-214; SSSL final paras 186-189', 'Treat as an analytical bridge, not an automatic rule that every accounting error violates PFUTP.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Financial misstatement evidence', 'Look for transaction-level commercial records, GST/tax records, bank flows, inventory/delivery evidence, counterparty confirmation and consistency across ledgers and statutory filings.', 'REL paras 67-159; SSSL final paras 53-115', 'Absence of several independent forms of evidence strengthens an inference of non-genuineness.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Circular fund-flow allegation', 'Circular movement by itself may be insufficient where loan/advance transactions are supported, occur in ordinary business, and are reflected in audited statements.', 'SSSL final paras 157-166', 'Trace the substance of each leg and test the explanation; temporal proximity alone is not conclusive.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Third-party examination', 'If a fraud theory depends on intermediary entities, failure to examine them or obtain corroboration can leave evidentiary gaps.', 'SSSL final para 166(iii)-(iv)', 'Record which entities were summoned, examined and made noticees.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Distinct transactions', 'Separate receipt of prior dues and later investment cannot be clubbed without credible evidence connecting the two transactions.', 'SSSL final paras 171-173', 'Require evidence of routing, common control, pre-arrangement or return of economic benefit.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Ultimate benefit / sale proceeds', 'Where alleged front allottees retain sale proceeds and no flow back is proved, that fact may undermine the allegation that allotment was financed for the promoter/company.', 'SSSL final paras 164-166 and 172-173', 'Always trace the eventual economic benefit, not only initial funding.');
insert into legal_tests (provision_or_issue, working_principle, paragraph_anchors, implementation_guardrail) values ('Interim versus final status', 'Interim findings are prima facie and may be displaced after replies, cross-examination and further evidence.', 'SSSL interim para 159; SSSL final paras 132-174', 'The chatbot must label procedural stage and prefer final findings when available.');
